export interface TriggerOptionDoc {
  trigger: Trigger;
  option: string;
  keys: Array<keyof TriggerOptions>;
  description: string;
  /** non-event kinds that take the option too (sendTask / receiveTask: --message) */
  alsoOn?: string[];
}

const TRIGGER_ROWS: Array<Omit<TriggerOptionDoc, 'option'>> = [
  { trigger: 'none', keys: [], description: 'plain event; the default for start/end/throw events in `add` (`retype` keeps the current trigger unless the suffix :none is given)' },
  { trigger: 'message', keys: ['message'], description: 'root bpmn:Message found by name, created when missing', alsoOn: ['sendTask', 'receiveTask'] },
  { trigger: 'timer', keys: ['timer', 'timerKind'], description: 'R/PT1H -> timeCycle, PT2D -> timeDuration, 2026-01-31T09:00:00Z -> timeDate (auto-classified)' },
  { trigger: 'error', keys: ['error', 'errorCode'], description: 'root bpmn:Error by name, created when missing' },
  { trigger: 'signal', keys: ['signal'], description: 'root bpmn:Signal by name, created when missing' },
  { trigger: 'escalation', keys: ['escalation', 'escalationCode'], description: 'root bpmn:Escalation by name, created when missing' },
  { trigger: 'conditional', keys: ['when'], description: 'condition expression' },
  { trigger: 'link', keys: ['link'], description: 'a throwing and a catching link event pair up by name' },
  { trigger: 'compensate', keys: [], description: 'compensation' },
  { trigger: 'terminate', keys: [], description: 'terminate end event' },
  { trigger: 'cancel', keys: [], description: 'transaction cancel' },
];

export const TRIGGER_OPTIONS: TriggerOptionDoc[] = TRIGGER_ROWS.map((row) => ({ ...row, option: triggerFlagUsage(row.keys) }));

export const NON_INTERRUPTING_DOC = '--non-interrupting (nonInterrupting): boundary events get cancelActivity=false, start events of an event sub-process isInterrupting=false; not allowed on error/cancel/compensate boundary events.';

export interface PlacementDoc {
  option: string;
  key: string;
  rule: string;
}

export const PLACEMENT_DOCS: PlacementDoc[] = [
  { option: '--after <X>', key: 'after', rule: 'X is a gateway or has no outgoing flow: append X -> node. X has exactly one outgoing flow: splice, X -> node -> old successor. Otherwise E_HAS_SUCCESSOR (say which flow).' },
  { option: '--before <Y>', key: 'before', rule: 'Symmetric: prepend before a join gateway or a node without incoming flow, else splice into its single incoming flow; several incoming flows -> E_HAS_PREDECESSOR.' },
  { option: '--after <X> --before <Y>', key: 'after + before', rule: 'Splice into the flow X -> Y (E_NO_FLOW / E_AMBIGUOUS_FLOW when there is none / several).' },
  { option: '--flow <F>', key: 'flow', rule: 'Splice into sequence flow F: A -> B becomes A -> node -> B. F keeps its name and condition and now ends at the node; it keeps its id too, unless the id named A and B (flow_aToB is renamed flow_aToNode).' },
  { option: '--in <S>', key: 'in', rule: 'Put the node into process / sub-process / participant S without connecting it (connect it afterwards).' },
  { option: '--on <A>', key: 'on', rule: 'Boundary events only: attach to activity A.' },
  { option: '--to <T>', key: 'to', rule: 'Additionally connect node -> T (a branch that re-joins the main path).' },
];

export const ID_CONVENTIONS = {
  rule: 'Elements are addressed by id only (names may repeat). New ids speak (never a hash or a running number) and follow the id conventions element-id-naming of the project\'s .bpmnlintrc declares, else the rule\'s defaults (see default), whatever ids the file already has; explicit ids (--id, "id") are taken as given; existing ids are never renamed for the conventions.',
  declared: 'where element-id-naming of the project\'s .bpmnlintrc is on, new ids take its prefix per BPMN type and its case (serviceTask_checkInvoice, flow_checkInvoiceToBookInvoice; required qualifier: timerStartEvent_monthly); a type it does not check, or switches off, takes bpmn-cli\'s prefix (see unchecked) with the first letter of the declared prefixes (Message_ next to Activity_) and the declared case; existing ids never change (W_ID_PREFIX_STALE); `bpmn show <file> --conventions` lists them, `bpmn guide conventions` has the rules',
  default: { element: '<prefix><nameSlug> with element-id-naming\'s default prefix of the type in camelCase (userTask_checkInvoice, gateway_invoiceOk, startEvent_orderReceived, participant_customer, lane_sales, dataObject_invoice)', unnamed: '<prefix><kindWord><Context> (gateway_afterCheckInvoice, event_timerOnReview, endEvent_afterTimerOnReview)', flow: 'flow_<source>To<Target> (flow_checkInvoiceToBookInvoice; message flows messageFlow_)', di: '<id>_di in files with DI of that form; BPMNShape_<id> / BPMNEdge_<id> in a new drawing (a long id cut at whole words: every DI id within 64 characters)' },
  unchecked: 'types element-id-naming does not check take bpmn-cli\'s prefix: the type\'s local name in lower camelCase (message_, signal_, error_, escalation_, laneSet_, category_, categoryValue_, property_, definitions_, timerEventDefinition_); a backing data object dataObjectItem_, a backing data store dataStoreItem_ (the references are dataObject_ / dataStore_). A process takes no prefix: a named one is its name in the case (orderToCash, the deployment key a call activity names), an unnamed one Process_1 (the next free number); a new pool\'s process takes the pool\'s name; a declared bpmn:Process prefix wins (process_orderToCash)',
  bodies: { camel: 'checkInvoice', pascal: 'CheckInvoice', snake: 'check_invoice', kebab: 'check-invoice' },
  bodiesNote: 'the declared case; `any` and no .bpmnlintrc: camelCase',
  unnamed: 'a word for the kind (events: Start, End, MessageStart, ErrorEnd, Timer, MessageThrow; other kinds only without context: gateway_parallel) + the context, minus what the prefix says: After <anchor>, Before <anchor>, On <host>, In <sub-process or pool>; after / before an unnamed anchor placed the same way, the nearest named anchor, once (endEvent_afterCheckInvoice after gateway_afterCheckInvoice, never AfterAfter...), with the anchor\'s kind where the id would repeat the anchor\'s (task_afterCheckInvoiceGateway); a name without a letter (123) names nothing; joins of a split: <gatewayId>Join (snake_case <gatewayId>_join, kebab-case <gatewayId>-join; a split id without the gateway prefix or case: that prefix + the gateway, gateway_checkJoin)',
  flow: '<flow prefix><source>To<Target> in the case (flow_checkInvoiceToBookInvoice, flow_check_invoice_to_book_invoice, flow_check-invoice-to-book-invoice); an end that begins with a number begins with From where the case wants a letter first',
  ends: 'a flow end or an anchor is named by its name, else by the speaking part of its id (checkInvoice; an unnamed element by its own kind and place, gateway_afterCheckInvoice -> afterCheckInvoice), else by a word for its kind (Gateway, End, Timer); an id with a number and a word speaks (gateway_afterCheck2024 -> afterCheck2024); hashes, numbers, machine ids and StartEvent_1 are never copied',
  length: 'at most 64 characters, a collision suffix included; a name gives at most 40 characters of words (a single longer word is cut at 40), and an id within 64 is not cut again; a longer one loses whole words the same way every time: the two ends of a flow share the room (each gives up its last words, never its first word, its last word with a letter before its Join or number, a word between two numbers, or the numbers before a number it ends with (x_2_2 stays whole), and a number left at the end of the id goes too where it reads like a collision suffix, and so does a filler word a cut would end on; of the cuts that fit, the one with the most words, then the most characters), a join\'s Join, a number and a collision suffix are kept; a word is cut inside only when no whole word is left to give up (each end of a flow keeps its first word, or its last where the two begin alike), and then in the longer end, keeping its Join or number (in both ends where the longer would keep fewer than 8 characters); a cut keeps a letter (a room that ends inside a leading number starts at the first word with a letter); a cut (a name\'s 40 characters, a body, a flow\'s end) never ends on a filler word, und, oder, an, die, the, of, ... (lieferantenbestellungVersenden, not ...VersendenUnd), the first word stays, and so does one between two numbers (startAfter2Und2)',
  collisions: 'the same edit gives the same ids; an unnamed gateway or activity whose id is taken, or whose body another id has (the unnamed gateway it follows), first spells out its kind where the prefix does not say it (gateway_parallelAfterCheckInvoice), then names the kind of the unnamed anchor it follows (task_afterCheckInvoiceGateway after gateway_afterCheckInvoice); a flow whose two ends begin with the same word keeps each end\'s last word when cut; a taken id gets 2, 3 under camelCase / PascalCase (after an id that ends in a digit No2, No3: serviceTask_step1No2, never serviceTask_step12, the id of Step 12), _2 under snake_case, -2 under kebab-case (an id the suffix would take past 64 characters loses whole words first) and W_ID_SUFFIXED (a repeated name, or unnamed elements only an index tells apart)',
  renames: 'a flow whose id names its ends in the current form (the id the conventions give a flow between them; an end also by its name, and in a batch by the id and name it had before a `set id=` / `name=` earlier in the batch) is renamed after its new ends when a splice, a bridge, a move or `set target=` changes them (its derived DI edge id follows; a flow without id gets one from its new ends, or the --flow-id of the add that splices into it, `id added`); a flow id in another form (Flow_AToB of bpmn-cli before 0.9, SequenceFlow_1, Flow_0k3x9qa) keeps it; every other id stays',
  transliteration: 'ä -> ae, ö -> oe, ü -> ue, ß -> ss; ø -> oe, å -> aa, æ -> ae, œ -> oe, ł -> l, þ -> th; other accents dropped (é -> e)',
  di: 'a full redraw keeps the ids of existing DI elements, planes and diagrams; new DI follows the DI ids of the file, cut like element ids to stay within 64 characters (a taken one gets _2); a DI shape or edge id derived from an element id (<id>_di, BPMNShape_<id>, Edge_<id>) follows `set <id> id=` as it follows a flow renamed after its ends; other DI ids, and plane and diagram ids, stay',
};

export const PLACEMENT_NOTES: string[] = [
  'Exactly one placement per add/move (after + before counts as one). Without any, the node is appended to the only process, unconnected.',
  'Flow options --flow-name / --flow-id / --condition / --language / --default describe the flow INTO the new node (from the anchor).',
  'move: several ids form a chain (the first takes the placement, each next one goes after the one before); the node the chain starts after (--after, the source of --flow) must lie outside it, else E_INVALID_PLACEMENT and nothing changes (a --before anchor in the chain is fine). A move that leaves its nodes where they are (move B --after A with A -> B) changes nothing and notes `task_b is already after task_a`; in a batch its flow keys still go to the flow into the first node, and "flowId" renames that flow. With --after <gateway> alone (an append) or --before <join> alone (a prepend) a node always moves.',
  'Branch order in the diagram: the default flow (else the first outgoing flow that leads to an end event, else the first one) continues straight; the other branches go alternately below and above it in declaration order (all below when a default flow exists). `bpmn order` changes the declaration order, `set <flowId> default=true` picks the continuation.',
  'Data objects, data stores, text annotations, lanes and pools take --in only; wire them with `bpmn connect`.',
  'A group takes no placement: --members <id,...> names what it is drawn around (`bpmn add order.bpmn group "Payment" --members serviceTask_pay,endEvent_paid`).',
];

